import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';

type ContractDetails = {
    id: number;
    employee_id: number;
    status: string | null;
    employee_number?: string | null;
    position?: string | null;
    contract_type?: string | null;
    start_date?: string | null;
    sign_date?: string | null;
    join_date?: string | null;
    end_date?: string | null;
    end_month?: string | null;
    end_year?: string | null;
    salary?: number | string | null;
    currency?: string | null;
    salary_cycle?: string | null;
    overtime_rate?: number | string | null;
    housing_allowance?: number | string | null;
    transportation_allowance?: number | string | null;
    description?: string | null;
    file?: string | null;
    employee?: { id: number; name: string } | null;
};

export default function ContractDetailsPage() {
    const { id } = useParams();
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const shouldPrint = searchParams.get('print') === '1';

    const [loading, setLoading] = useState(true);
    const [data, setData] = useState<ContractDetails | null>(null);
    const [error, setError] = useState<string | null>(null);

    const contractId = useMemo(() => Number(id), [id]);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            if (!contractId || Number.isNaN(contractId)) {
                setError('رقم العقد غير صحيح');
                setLoading(false);
                return;
            }
            setLoading(true);
            setError(null);
            try {
                const res = await apiGet<{ data: ContractDetails }>({
                    endpoint: endpoints.hrContract.show + contractId,
                });
                if (!cancelled) setData(res.data.data);
            } catch {
                if (!cancelled) setError('تعذر تحميل بيانات العقد');
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, [contractId]);

    useEffect(() => {
        if (!loading && shouldPrint) {
            window.print();
        }
    }, [loading, shouldPrint]);

    return (
        <div className="w-full mt-6 mb-20">
            <div className="flex flex-row items-center justify-between mb-6">
                <UnderlineHeading text="تفاصيل العقد" />
                <div className="flex gap-3">
                    <SecondaryButton type="button" onClick={() => navigate('/human-resources/contract-management')}>
                        رجوع
                    </SecondaryButton>
                    {data?.file ? (
                        <PrimaryButton type="button" onClick={() => window.open(data.file as string, '_blank')}>
                            فتح الملف
                        </PrimaryButton>
                    ) : null}
                </div>
            </div>

            {loading ? <p className="text-sm text-[#625E74]">جاري التحميل…</p> : null}
            {error ? <p className="text-sm text-red-600">{error}</p> : null}

            {!loading && !error && data ? (
                <div className="rounded-lg border border-[#E8E7EA] bg-white p-4 shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-[#625E74]">
                        <div>
                            <span className="text-primery-blue-900 font-medium">الموظف:</span> {data.employee?.name || '—'}
                        </div>
                        <div>
                            <span className="text-primery-blue-900 font-medium">الحالة:</span> {data.status || '—'}
                        </div>
                        <div>
                            <span className="text-primery-blue-900 font-medium">بداية العقد:</span> {data.start_date || '—'}
                        </div>
                        <div>
                            <span className="text-primery-blue-900 font-medium">نهاية العقد:</span> {data.end_date || '—'}
                        </div>
                        <div>
                            <span className="text-primery-blue-900 font-medium">الراتب:</span>{' '}
                            {data.salary !== null && data.salary !== undefined ? String(data.salary) : '—'} {data.currency || ''}
                        </div>
                        <div>
                            <span className="text-primery-blue-900 font-medium">دورة القبض:</span> {data.salary_cycle || '—'}
                        </div>
                        <div className="md:col-span-2">
                            <span className="text-primery-blue-900 font-medium">الوصف:</span> {data.description || '—'}
                        </div>
                    </div>
                </div>
            ) : null}
        </div>
    );
}

